from glob import glob
def task_func(directory, string):
    matching_files = []
    for filepath in glob(directory + '/**/*.json', recursive=True):
        with open(filepath, 'r') as f:
            try:
                data = json.load(f)
                if search_string(data, string):
                    matching_files.append(filepath)
            except json.JSONDecodeError:
                continue
    return matching_files
def search_string(data, target):
    if isinstance(data, str):
        return data == target
    elif isinstance(data, dict):
        for value in data.values():
            if search_string(value, target):
                return True
    elif isinstance(data, list):
        for item in data:
            if search_string(item, target):
                return True
    return False

