import json
import os
PREFIXES = ["is_", "has_", "can_", "should_"]
def task_func(directory):
    prefix_counts = {prefix: 0 for prefix in PREFIXES}

    for filename in os.listdir(directory):
        if filename.endswith('.json'):
            file_path = os.path.join(directory, filename)
            with open(file_path, 'r') as f:
                data = json.load(f)
                if isinstance(data, dict):
                    data = [data]
                for item in data:
                    for key in item:
                        for prefix in PREFIXES:
                            if key.startswith(prefix):
                                prefix_counts[prefix] += 1
    return prefix_counts

import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b')
    def process(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                v = process(v)
                new_dict[k] = v
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                item = process(item)
                new_list.append(item)
            return new_list
        elif isinstance(obj, str):
            if email_pattern.search(obj):
                return REPLACE_NONE
            else:
                return obj
        else:
            return obj
    processed = process(data)
    def extract_values(obj):
        vals = []
        if isinstance(obj, dict):
            for v in obj.values():
                vals.extend(extract_values(v))
        elif isinstance(obj, list):
            for v in obj:
                vals.extend(extract_values(v))
        else:
            vals.append(obj)
        return vals
    all_vals = extract_values(processed)
    counts = Counter(all_vals)
    return {"data": processed, "value_counts": counts}

